--------------------------------------------------------------------------------
-- mlp_shape_tb.vhd
--
-- Run-time shape reconfiguration test.
--
-- Replays shape_stim.txt (generated by verify/gen_shape_stim.py): for each of
-- four networks, in one continuous run and with no reset between them, it
-- writes the per-layer width registers, loads weights and biases over
-- AXI-Lite, streams input vectors, and checks every output and the cycle
-- counter against a bit-exact reference computed on the real network shape.
--
-- Record format, one per line:
--   L <text>                     label (printed)
--   W <addr> <value>             AXI-Lite write
--   V <x0> ... <x63>             input vector
--   E <o0> <o1> <o2> <cycles>    expected outputs and cycle count
--
-- Simulation only; not part of the synthesised design.
--------------------------------------------------------------------------------
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use std.textio.all;

entity mlp_shape_tb is
    generic ( STIM_FILE : string := "shape_stim.txt" );
end entity mlp_shape_tb;

architecture sim of mlp_shape_tb is

    constant CLK_PERIOD : time := 8 ns;          -- 125 MHz

    signal clk      : std_logic := '0';
    signal aresetn  : std_logic := '0';
    signal sim_done : boolean := false;

    signal awaddr  : std_logic_vector(19 downto 0) := (others => '0');
    signal awprot  : std_logic_vector(2 downto 0)  := (others => '0');
    signal awvalid : std_logic := '0';
    signal awready : std_logic;
    signal wdata   : std_logic_vector(31 downto 0) := (others => '0');
    signal wstrb   : std_logic_vector(3 downto 0)  := "1111";
    signal wvalid  : std_logic := '0';
    signal wready  : std_logic;
    signal bresp   : std_logic_vector(1 downto 0);
    signal bvalid  : std_logic;
    signal bready  : std_logic := '1';
    signal araddr  : std_logic_vector(19 downto 0) := (others => '0');
    signal arprot  : std_logic_vector(2 downto 0)  := (others => '0');
    signal arvalid : std_logic := '0';
    signal arready : std_logic;
    signal rdata   : std_logic_vector(31 downto 0);
    signal rresp   : std_logic_vector(1 downto 0);
    signal rvalid  : std_logic;
    signal rready  : std_logic := '1';

    signal axis_tdata  : std_logic_vector(31 downto 0) := (others => '0');
    signal axis_tvalid : std_logic := '0';
    signal axis_tready : std_logic;
    signal axis_tlast  : std_logic := '0';

    signal o_led : std_logic_vector(7 downto 0);
    signal d1, d2, d3, d4, d5, d6 : std_logic;

    type vec64_t is array(0 to 63) of integer;

begin

    clk_proc : process
    begin
        while not sim_done loop
            clk <= '0'; wait for CLK_PERIOD/2;
            clk <= '1'; wait for CLK_PERIOD/2;
        end loop;
        wait;
    end process;

    DUT : entity work.mlp_axi_wrapper
        generic map (C_S_AXI_DATA_WIDTH => 32, C_S_AXI_ADDR_WIDTH => 20)
        port map (
            S_AXI_ACLK => clk, S_AXI_ARESETN => aresetn,
            S_AXI_AWADDR => awaddr, S_AXI_AWPROT => awprot,
            S_AXI_AWVALID => awvalid, S_AXI_AWREADY => awready,
            S_AXI_WDATA => wdata, S_AXI_WSTRB => wstrb,
            S_AXI_WVALID => wvalid, S_AXI_WREADY => wready,
            S_AXI_BRESP => bresp, S_AXI_BVALID => bvalid, S_AXI_BREADY => bready,
            S_AXI_ARADDR => araddr, S_AXI_ARPROT => arprot,
            S_AXI_ARVALID => arvalid, S_AXI_ARREADY => arready,
            S_AXI_RDATA => rdata, S_AXI_RRESP => rresp,
            S_AXI_RVALID => rvalid, S_AXI_RREADY => rready,
            S_AXIS_ACLK => clk, S_AXIS_ARESETN => aresetn,
            S_AXIS_TDATA => axis_tdata, S_AXIS_TVALID => axis_tvalid,
            S_AXIS_TREADY => axis_tready, S_AXIS_TLAST => axis_tlast,
            o_led => o_led,
            dbg_data_in_pulse => d1, dbg_layer1_done => d2, dbg_layer2_done => d3,
            dbg_layer3_done => d4, dbg_layer4_done => d5, dbg_mlp_busy => d6
        );

    stim : process
        -- Same AXI-Lite primitives as mlp_verify_tb
        procedure axi_write(addr : integer; val : integer) is
        begin
            wait until rising_edge(clk);
            awaddr  <= std_logic_vector(to_unsigned(addr, 20));
            wdata   <= std_logic_vector(to_signed(val, 32));
            awvalid <= '1'; wvalid <= '1';
            wait until rising_edge(clk) and awready = '1' and wready = '1';
            awvalid <= '0'; wvalid <= '0';
            wait until rising_edge(clk) and bvalid = '1';
        end procedure;

        procedure axi_read(addr : integer; val : out integer) is
        begin
            wait until rising_edge(clk);
            araddr <= std_logic_vector(to_unsigned(addr, 20));
            arvalid <= '1';
            wait until rising_edge(clk) and arready = '1';
            arvalid <= '0';
            wait until rising_edge(clk) and rvalid = '1';
            val := to_integer(signed(rdata(15 downto 0)));
        end procedure;

        procedure send_vec(v : vec64_t) is
        begin
            for w in 0 to 31 loop
                axis_tdata <= std_logic_vector(to_signed(v(2*w+1), 16)) &
                              std_logic_vector(to_signed(v(2*w),   16));
                axis_tvalid <= '1';
                if w = 31 then axis_tlast <= '1'; else axis_tlast <= '0'; end if;
                wait until rising_edge(clk) and axis_tready = '1';
            end loop;
            wait until rising_edge(clk);
            axis_tvalid <= '0';
            axis_tlast  <= '0';
        end procedure;

        file     f     : text;
        variable l     : line;
        variable tag   : character;
        variable a, v  : integer;
        variable vec   : vec64_t;
        variable e0, e1, e2, ec : integer;
        variable g0, g1, g2, gc, st, guard : integer;
        variable n_inf, n_fail, n_cyc_fail : integer := 0;
        variable good  : boolean;
    begin
        aresetn <= '0';
        wait for CLK_PERIOD * 20;
        aresetn <= '1';
        wait for CLK_PERIOD * 5;

        file_open(f, STIM_FILE, read_mode);
        while not endfile(f) loop
            readline(f, l);
            next when l'length = 0;
            read(l, tag);
            case tag is
                when 'L' =>
                    report "==== " & l.all severity note;
                when 'W' =>
                    read(l, a); read(l, v);
                    axi_write(a, v);
                when 'V' =>
                    for i in 0 to 63 loop read(l, vec(i)); end loop;
                    send_vec(vec);
                    guard := 0;
                    loop
                        axi_read(16#00004#, st);
                        exit when (st mod 2) = 1;          -- done bit
                        guard := guard + 1;
                        assert guard < 2000
                            report "TIMEOUT: done was never asserted" severity failure;
                    end loop;
                    axi_read(16#00100#, g0);
                    axi_read(16#00104#, g1);
                    axi_read(16#00108#, g2);
                    axi_read(16#00010#, gc);               -- cycle counter
                when 'E' =>
                    read(l, e0); read(l, e1); read(l, e2); read(l, ec);
                    n_inf := n_inf + 1;
                    good := (g0 = e0) and (g1 = e1) and (g2 = e2);
                    if not good then
                        n_fail := n_fail + 1;
                        if n_fail <= 5 then
                            report "MISMATCH #" & integer'image(n_inf) &
                                " expected [" & integer'image(e0) & ", " &
                                integer'image(e1) & ", " & integer'image(e2) &
                                "] got [" & integer'image(g0) & ", " &
                                integer'image(g1) & ", " & integer'image(g2) & "]"
                                severity warning;
                        end if;
                    end if;
                    if gc /= ec then
                        n_cyc_fail := n_cyc_fail + 1;
                        if n_cyc_fail <= 5 then
                            report "CYCLES #" & integer'image(n_inf) &
                                " expected " & integer'image(ec) &
                                " got " & integer'image(gc) severity warning;
                        end if;
                    end if;
                when others =>
                    null;
            end case;
        end loop;
        file_close(f);

        report "RESULT inferences=" & integer'image(n_inf) &
               " output_mismatches=" & integer'image(n_fail) &
               " cycle_mismatches=" & integer'image(n_cyc_fail) severity note;
        sim_done <= true;
        wait;
    end process;

end architecture sim;
